repositoryCalls.expression:
.from("user_preferences").upsert({
    user_id:user.id, locale, currency, unit_system:unitSystem, country_code:country??null,
    updated_at:new Date().toISOString()
  })

.from("calculator_source_evidence").insert({
    calculator_id: calculatorId, label, url, source_kind: sourceKind, reviewed_by: user.id
  })

.rpc("record_calculator_qa_decision", {
    p_calculator_id: calculatorId, p_check_type: checkType, p_status: status, p_details: details
  })

.rpc("transition_calculator_with_audit", {
    p_calculator_id: calculatorId, p_expected_lifecycle: current, p_target_lifecycle: target
  })

.from("webhook_deliveries").update({
        status: deadLetter ? "dead_letter" : "failed",
        last_error: sendError instanceof Error ? sendError.message.slice(0, 500) : "Webhook delivery failed",
        next_attempt_at: nextWebhookRetry(attempt).toISOString()
      }).eq("id", delivery.id)

.from("organization_members").select("user_id", { count: "exact", head: true }).eq("organization_id", organizationId),
    supabase.from("organization_invitations").select("id", { count: "exact", head: true }).eq("organization_id", organizationId).is("accepted_at", null).gt("expires_at", new Date().toISOString())
  ])

.from("business_projects").insert({
    organization_id: organizationId,
    name,
    description: description || null,
    created_by: user.id
  })

.from("client_workspaces").insert({
    organization_id: organizationId,
    name,
    client_reference: reference || null,
    created_by: user.id
  })

.from("business_webhook_endpoints").select("id,name,endpoint_url,event_types,status,created_at").eq("organization_id", organizationId).order("created_at", { ascending: false })),
    readAutomation(supabase.from("webhook_deliveries").select("id,status").eq("organization_id", organizationId).order("created_at", { ascending: false }).limit(1000))
  ])

.from("client_workspaces").select("id,name,client_reference,created_at").eq("organization_id", organizationId).order("created_at", { ascending: false }).limit(12)),
    readWorkspace(supabase.from("organization_audit_log").select("id,action,entity_type,created_at").eq("organization_id", organizationId).order("created_at", { ascending: false }).limit(8))
  ])

